#pragma once
#include "work_follow_through.hpp"
#include "work_result_source_codec.hpp"
#include "resident/domains/interaction/communication_ref_codec.hpp"
namespace hanmo::resident::work_follow_through_codec {
using communication_ref_codec::source;using communication_ref_codec::refs;
template<class A>Status result(A&a,WorkResultSource&v){return work_source_codec::result(a,v);}
template<class A>Status follow_through(A&a,AcceptedWorkFollowThroughRef&v){Integer tag=v.index();a.field("kind",tag);if(!a.status().ok)return a.status();if(tag<0||tag>1)return a.reject("UnknownAcceptedWorkFollowThrough");if(a.reading()){if(tag==0){if(!prepare_checkpoint_default_values<OutcomeApplication>(a).ok)return a.status();v=OutcomeApplication{};}else {if(!prepare_checkpoint_default_values<ReportBack>(a).ok)return a.status();v=ReportBack{};}}return std::visit([&](auto&x){a.field("task_id",x.task_id);a.object("work_result_ref",[&](auto&c){return result(c,x.work_result_ref);});using T=std::decay_t<decltype(x)>;if constexpr(std::is_same_v<T,OutcomeApplication>){a.field("objective_id",x.objective_id);a.object("program_ref",[&](auto&c){return source(c,x.program_ref);});a.field("target_line_id",x.target_line_id);dynamic_codec::enumeration(a,"application_kind",x.application_kind,2);return a.object("original_application_ref",[&](auto&c){return source(c,x.original_application_ref);});}else {a.field("report_requirement_id",x.report_requirement_id);a.object("report_content_ref",[&](auto&c){return source(c,x.report_content_ref);});a.object("original_reporting_obligation_ref",[&](auto&c){return source(c,x.original_reporting_obligation_ref);});return a.object("addressee",[&](auto&c){return communication_ref_codec::address(c,x.addressee);});}},v);}
template<class A>Status unavailable(A&a,WorkFollowThroughUnavailableSource&v){Integer tag=v.index();a.field("kind",tag);if(!a.status().ok)return a.status();if(tag<0||tag>3)return a.reject("UnknownWorkFollowThroughUnavailable");if(a.reading()){if(tag==0){if(!prepare_checkpoint_default_values<PatrolApplicationUnavailable>(a).ok)return a.status();v=PatrolApplicationUnavailable{};}else if(tag==1){if(!prepare_checkpoint_default_values<ImprovementApplicationUnavailable>(a).ok)return a.status();v=ImprovementApplicationUnavailable{};}else if(tag==2){if(!prepare_checkpoint_default_values<FacilityApplicationUnavailable>(a).ok)return a.status();v=FacilityApplicationUnavailable{};}else {if(!prepare_checkpoint_default_values<ReportBackUnavailable>(a).ok)return a.status();v=ReportBackUnavailable{};}}return std::visit([&](auto&x){using T=std::decay_t<decltype(x)>;if constexpr(std::is_same_v<T,ReportBackUnavailable>){a.object("reporting_obligation_ref",[&](auto&c){return source(c,x.reporting_obligation_ref);});return a.object("report_terminal_ref",[&](auto&c){return source(c,x.report_terminal_ref);});}else {a.object("application_terminal_ref",[&](auto&c){return source(c,x.application_terminal_ref);});if constexpr(std::is_same_v<T,PatrolApplicationUnavailable>){a.object("program_ref",[&](auto&c){return source(c,x.program_ref);});return a.field("target_line_id",x.target_line_id);}else if constexpr(std::is_same_v<T,ImprovementApplicationUnavailable>){return a.object("work_ref",[&](auto&c){c.field("owner_domain",x.work_ref.owner_domain);dynamic_codec::enumeration(c,"kind",x.work_ref.kind,2);return c.field("work_id",x.work_ref.work_id);});}else return a.object("asset_ref",[&](auto&c){return source(c,x.asset_ref);});}},v);}
template<class A>Status terminal(A&a,FollowThroughTerminalView&v){a.object("original_obligation_ref",[&](auto&c){return source(c,v.original_obligation_ref);});a.object("accepted_goal_ref",[&](auto&c){return source(c,v.accepted_goal_ref);});a.object("work_result_ref",[&](auto&c){return result(c,v.work_result_ref);});a.field("source_terminal_id",v.source_terminal_id);a.field("source_schema",v.source_schema);a.object("actual_cause_ref",[&](auto&c){return source(c,v.actual_cause_ref);});a.object("continuity_source_ref",[&](auto&c){return source(c,v.continuity_source_ref);});refs(a,"preserved_actual_result_refs",v.preserved_actual_result_refs);return a.object("effective_game_time",[&](auto&c){return dynamic_codec::exact_moment(c,v.effective_game_time);});}
template<class A>Status scope(A&a,S3WorkCommission&v){a.field("work_id",v.work_id);a.object("accepted_task_ref",[&](auto&c){return source(c,v.accepted_task_ref);});a.object("work_acceptance_source_ref",[&](auto&c){return source(c,v.work_acceptance_source_ref);});return a.object("expense_terms_ref",[&](auto&c){return source(c,v.expense_terms_ref);});}
// 原 Work terminal 地址的同一字段表，CS 与费用叶借读，不复制终局载荷。
template<class A>Status commission_terminal_ref(A&a,WorkCommissionTerminal&v){a.field("task_id",v.task_id);a.object("accepted_task_ref",[&](auto&c){return source(c,v.accepted_task_ref);});a.field("work_id",v.work_id);a.field("task_terminal_fact_id",v.task_terminal_fact_id);return a.field("source_schema",v.source_schema);}
template<class A>Status termination_basis(A&a,WorkCommissionTerminationBasis&v){Integer tag=v.index();a.field("kind",tag);if(!a.status().ok)return a.status();if(tag<0||tag>1)return a.reject("UnknownWorkCommissionTerminationBasis");if(a.reading()){if(tag==0){if(!prepare_checkpoint_default_values<WorkExecutionStopped>(a).ok)return a.status();v=WorkExecutionStopped{};}else {if(!prepare_checkpoint_default_values<AcceptedFollowThroughStopped>(a).ok)return a.status();v=AcceptedFollowThroughStopped{};}}if(auto*p=std::get_if<WorkExecutionStopped>(&v))return a.object("stopped_work_result_ref",[&](auto&c){return result(c,p->stopped_work_result_ref);});auto&p=std::get<AcceptedFollowThroughStopped>(v);a.object("completed_work_result_ref",[&](auto&c){return result(c,p.completed_work_result_ref);});a.sequence("failed_follow_through_refs",p.failed_follow_through_refs,[](auto&c,auto&x){return follow_through(c,x);});a.sequence("source_terminal_refs",p.source_terminal_refs,[](auto&c,auto&x){return unavailable(c,x);});return refs(a,"fulfilled_goal_refs",p.fulfilled_goal_refs);}
template<class A>Status task_terminal(A&a,WorkCommissionTaskTerminalSource&v){a.field("task_terminal_fact_id",v.task_terminal_fact_id);a.object("accepted_scope_ref",[&](auto&c){return scope(c,v.accepted_scope_ref);});a.object("accepted_terms_ref",[&](auto&c){return commitment_codec::terms(c,v.accepted_terms_ref);});a.object("work_result_ref",[&](auto&c){return result(c,v.work_result_ref);});a.object("termination_basis",[&](auto&c){return termination_basis(c,v.termination_basis);});refs(a,"preserved_fulfilment_refs",v.preserved_fulfilment_refs);refs(a,"remaining_financial_or_return_refs",v.remaining_financial_or_return_refs);return a.object("effective_game_time",[&](auto&c){return dynamic_codec::exact_moment(c,v.effective_game_time);});}
}
